import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, Easing, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadCormorant = makeLoadFont('CormorantGaramond');
const loadInter = makeLoadFont('Inter');

// Module-level Google Font loading
const { fontFamily: cormorantFamily } = loadCormorant();
const { fontFamily: interFamily } = loadInter();



export type SpacetimeBendingProps = Record<string, any>;

interface Point {
  x: number;
  y: number;
}

// Deterministic general relativity-inspired step solver for photons
const computePhotonPath = (
  startX: number,
  startY: number,
  vx: number,
  vy: number,
  cx: number,
  cy: number,
  gm: number,
  steps: number,
  horizonRadius: number
): Point[] => {
  const path: Point[] = [];
  let px = startX;
  let py = startY;
  let vxCurr = vx;
  let vyCurr = vy;

  for (let i = 0; i < steps; i++) {
    path.push({ x: px, y: py });

    const dx = px - cx;
    const dy = py - cy;
    const r2 = dx * dx + dy * dy;
    const r = Math.sqrt(r2);

    if (r < horizonRadius) {
      // Light is captured, smoothly spiral towards singularity center
      const pull = 0.85;
      px = px + (cx - px) * pull;
      py = py + (cy - py) * pull;
      path.push({ x: px, y: py });
      break;
    }

    // Doubled Newtonian gravitational force to approximate GR deflection
    const force = (gm * 2.0) / (r2 * r + 0.1); 
    const ax = -force * dx;
    const ay = -force * dy;

    vxCurr += ax;
    vyCurr += ay;

    // Limit maximum speed to avoid numerical issues very near singularity
    const speed = Math.sqrt(vxCurr * vxCurr + vyCurr * vyCurr);
    const maxSpeed = 35;
    if (speed > maxSpeed) {
      vxCurr = (vxCurr / speed) * maxSpeed;
      vyCurr = (vyCurr / speed) * maxSpeed;
    }

    px += vxCurr;
    py += vyCurr;
  }
  return path;
};

// Warp a coordinate towards a gravitational center to create embedding model
const warpPoint = (
  x: number,
  y: number,
  cx: number,
  cy: number,
  w: number,
  strength: number,
  massRadius: number
) => {
  const dx = x - cx;
  const dy = y - cy;
  const r2 = dx * dx + dy * dy;
  const r = Math.sqrt(r2);
  const rEps = Math.max(r, 0.1);

  // Smooth rational pull falloff
  const warpScale = 220;
  const pull = strength * (1.0 / (1.0 + Math.pow(rEps / warpScale, 1.5)));
  const actualPull = pull * w;

  return {
    x: x - dx * actualPull,
    y: y - dy * actualPull,
  };
};

const SpacetimeBending: React.FC<SpacetimeBendingProps> = ({
  backgroundColor = "#0c0c0e",
  transparentBackground = false,
  durationInSeconds = 12,
  gridColor = "#58c4dd",
  gridOpacity = 0.25,
  warpStrength = 0.85,
  massSize = 65,
  photonSpeed = 14,
  gravityStrength = 38000,
  titleFontSize = 42,
  bodyFontSize = 17,
  metaFontSize = 14,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Position coordinates matching horizontal layout guidelines
  const cx = width * 0.65;
  const cy = height * 0.5;

  // Timeline & Transition calculation
  const massIntroProgress = interpolate(frame, [60, 120], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const blackHoleScale = Easing.bezier(0.25, 1, 0.5, 1)(massIntroProgress);

  const warpProgress = interpolate(frame, [90, 180], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const w = Easing.bezier(0.42, 0, 0.58, 1)(warpProgress);

  // Generate star coordinates deterministically
  const backgroundStars = React.useMemo(() => {
    const stars = [];
    for (let i = 0; i < 50; i++) {
      const sx = random(`star-x-${i}`) * width;
      const sy = random(`star-y-${i}`) * height;
      const size = random(`star-size-${i}`) * 1.5 + 0.5;
      const opacity = random(`star-op-${i}`) * 0.4 + 0.2;
      stars.push({ x: sx, y: sy, size, opacity });
    }
    return stars;
  }, [width, height]);

  // Build the warped grid paths
  const warpedGridLines = React.useMemo(() => {
    const lines: string[] = [];
    const hStep = 60;
    const vStep = 60;
    const samples = 40;

    // Horizontal Lines
    for (let y = cy - 600; y <= cy + 600; y += hStep) {
      let pathD = "";
      for (let i = 0; i <= samples; i++) {
        const x = cx - 800 + (i / samples) * 1600;
        const wp = warpPoint(x, y, cx, cy, w, warpStrength, massSize);
        pathD += (i === 0 ? "M " : " L ") + `${wp.x} ${wp.y}`;
      }
      lines.push(pathD);
    }

    // Vertical Lines
    for (let x = cx - 800; x <= cx + 800; x += vStep) {
      let pathD = "";
      for (let i = 0; i <= samples; i++) {
        const y = cy - 600 + (i / samples) * 1200;
        const wp = warpPoint(x, y, cx, cy, w, warpStrength, massSize);
        pathD += (i === 0 ? "M " : " L ") + `${wp.x} ${wp.y}`;
      }
      lines.push(pathD);
    }

    return lines;
  }, [cx, cy, w, warpStrength, massSize]);

  // Photon shooting paths
  const photonShootStartFrame = 170;
  const startX = cx - 750;

  const photonPaths = React.useMemo(() => {
    const steps = 180;
    const horizonCollision = massSize * 0.65;
    
    // Path 1: High distance (weak deflection)
    const p1 = computePhotonPath(startX, cy - 230, photonSpeed, 0, cx, cy, gravityStrength, steps, horizonCollision);
    // Path 2: Medium distance (strong deflection)
    const p2 = computePhotonPath(startX, cy - 135, photonSpeed, 0, cx, cy, gravityStrength, steps, horizonCollision);
    // Path 3: Extremely close (captured into event horizon)
    const p3 = computePhotonPath(startX, cy - 80, photonSpeed, 0, cx, cy, gravityStrength, steps, horizonCollision);

    return [p1, p2, p3];
  }, [cx, cy, photonSpeed, gravityStrength, massSize]);

  const photonFrame = frame - photonShootStartFrame;

  // Left panel informational transitions (Manim style slide-ups)
  const text1Opacity = interpolate(frame, [10, 25, 80, 90], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const text1Y = interpolate(frame, [10, 25], [15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const text2Opacity = interpolate(frame, [95, 110, 185, 195], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const text2Y = interpolate(frame, [95, 110], [15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const text3Opacity = interpolate(frame, [200, 215], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const text3Y = interpolate(frame, [200, 215], [15, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const getSvgPathD = (points: Point[]) => {
    if (points.length === 0) return "";
    return points.reduce((acc, p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `${acc} L ${p.x} ${p.y}`), "");
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Background Starfield */}
      {backgroundStars.map((star, idx) => (
        <div
          key={idx}
          style={{
            position: "absolute",
            left: star.x,
            top: star.y,
            width: star.size,
            height: star.size,
            backgroundColor: "#ffffff",
            borderRadius: "50%",
            opacity: star.opacity,
            transition: "none",
          }}
        />
      ))}

      {/* Main Spacetime Visualization SVG */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          transition: "none",
        }}
      >
        <defs>
          <radialGradient id="accretionGlow" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#ff7675" stopOpacity={0.8 * blackHoleScale} />
            <stop offset="25%" stopColor="#e17055" stopOpacity={0.5 * blackHoleScale} />
            <stop offset="65%" stopColor="#fdcb6e" stopOpacity={0.15 * blackHoleScale} />
            <stop offset="100%" stopColor="#000000" stopOpacity={0} />
          </radialGradient>
          <radialGradient id="singularityGlow" cx="50%" cy="50%" r="50%">
            <stop offset="72%" stopColor="#000000" stopOpacity={1} />
            <stop offset="100%" stopColor="#0c0c0e" stopOpacity={0} />
          </radialGradient>
        </defs>

        {/* Spacetime coordinate mesh */}
        <g opacity={gridOpacity}>
          {warpedGridLines.map((d, index) => (
            <path
              key={index}
              d={d}
              fill="none"
              stroke={gridColor}
              strokeWidth="1.5"
              style={{ transition: "none" }}
            />
          ))}
        </g>

        {/* Black Hole Visual Elements */}
        {blackHoleScale > 0 && (
          <g>
            {/* Soft Accretion Glow */}
            <circle
              cx={cx}
              cy={cy}
              r={massSize * 3.5}
              fill="url(#accretionGlow)"
              style={{ transition: "none" }}
            />

            {/* Orbiting Accretion Matter Ring 1 */}
            <circle
              cx={cx}
              cy={cy}
              r={massSize * 1.3}
              fill="none"
              stroke="#e17055"
              strokeWidth="2.5"
              strokeDasharray="20 40 80 50"
              style={{
                transform: `rotate(${-frame * 1.5}deg)`,
                transformOrigin: `${cx}px ${cy}px`,
                opacity: 0.8 * blackHoleScale,
                transition: "none",
              }}
            />

            {/* Orbiting Accretion Matter Ring 2 */}
            <circle
              cx={cx}
              cy={cy}
              r={massSize * 1.7}
              fill="none"
              stroke="#fdcb6e"
              strokeWidth="1.5"
              strokeDasharray="50 80 20 60"
              style={{
                transform: `rotate(${frame * 0.9}deg)`,
                transformOrigin: `${cx}px ${cy}px`,
                opacity: 0.6 * blackHoleScale,
                transition: "none",
              }}
            />

            {/* Einstein Ring / Gravitational Lensing Halo */}
            <circle
              cx={cx}
              cy={cy}
              r={massSize * 1.08}
              fill="none"
              stroke="#ffffff"
              strokeWidth={3 * blackHoleScale}
              strokeOpacity={0.45 * blackHoleScale}
              style={{
                filter: "blur(1.5px)",
                transition: "none",
              }}
            />

            {/* Black Hole Singularity Sphere */}
            <circle
              cx={cx}
              cy={cy}
              r={massSize * blackHoleScale}
              fill="url(#singularityGlow)"
              style={{ transition: "none" }}
            />
            <circle
              cx={cx}
              cy={cy}
              r={massSize * 0.72 * blackHoleScale}
              fill="#000000"
              style={{ transition: "none" }}
            />
          </g>
        )}

        {/* Photons (Geodesic Beams of Light) */}
        {photonFrame > 0 &&
          photonPaths.map((path, idx) => {
            const trailingPath = path.slice(0, Math.min(photonFrame, path.length));
            const currentPos = trailingPath[trailingPath.length - 1];
            const isFinished = photonFrame >= path.length;

            const trailColor =
              idx === 0 ? "#2ECC71" : idx === 1 ? "#F1C40F" : "#E74C3C";

            // If path was captured, fade out trail smoothly at the end
            const trailOpacity =
              idx === 2 && isFinished
                ? interpolate(photonFrame, [path.length, path.length + 15], [0.8, 0], { extrapolateRight: "clamp" })
                : 0.85;

            return (
              <g key={idx} opacity={trailOpacity}>
                {/* Trajectory line */}
                <path
                  d={getSvgPathD(trailingPath)}
                  fill="none"
                  stroke={trailColor}
                  strokeWidth="3.5"
                  strokeLinecap="round"
                  style={{ transition: "none" }}
                />

                {/* Leading Photon Head */}
                {currentPos && !isFinished && (
                  <g>
                    <circle
                      cx={currentPos.x}
                      cy={currentPos.y}
                      r="9"
                      fill="#ffffff"
                      style={{ filter: "blur(1px)", transition: "none" }}
                    />
                    <circle
                      cx={currentPos.x}
                      cy={currentPos.y}
                      r="5"
                      fill={trailColor}
                      style={{ transition: "none" }}
                    />
                  </g>
                )}
              </g>
            );
          })}
      </svg>

      {/* Side Explanation Board (Horizontal Flow Layout) */}
      <div
        style={{
          position: "absolute",
          left: width * 0.05,
          top: height * 0.12,
          width: width * 0.28,
          height: height * 0.76,
          backgroundColor: "rgba(10, 10, 12, 0.82)",
          border: "1px solid rgba(88, 196, 221, 0.18)",
          borderRadius: "16px",
          padding: "40px 32px",
          display: "flex",
          flexDirection: "column",
          boxShadow: "0 20px 50px rgba(0,0,0,0.65)",
          overflow: "hidden",
          transition: "none",
        }}
      >
        {/* Stage 1: Flat space */}
        {text1Opacity > 0 && (
          <div
            style={{
              transform: `translateY(${text1Y}px)`,
              opacity: text1Opacity,
              position: "absolute",
              inset: "40px 32px",
              display: "flex",
              flexDirection: "column",
              justifyContent: "flex-start",
              transition: "none",
            }}
          >
            <div
              style={{
                color: "#58c4dd",
                fontFamily: interFamily,
                fontSize: `${metaFontSize}px`,
                fontWeight: "bold",
                letterSpacing: "3px",
                marginBottom: "12px",
              }}
            >
              STAGE 1: MINKOWSKI METRIC
            </div>
            <div
              style={{
                fontFamily: cormorantFamily,
                fontSize: `${titleFontSize}px`,
                color: "#ffffff",
                lineHeight: "1.2",
                marginBottom: "20px",
              }}
            >
              Flat Spacetime
            </div>
            <div
              style={{
                fontFamily: interFamily,
                fontSize: `${bodyFontSize}px`,
                color: "#b2bec3",
                lineHeight: "1.7",
                marginBottom: "32px",
              }}
            >
              In the absence of any mass or energy density, the coordinate fabric of the universe is uniform and flat. Photons travel in perfectly straight lines.
            </div>
            <div
              style={{
                backgroundColor: "rgba(88, 196, 221, 0.04)",
                border: "1px solid rgba(88, 196, 221, 0.15)",
                borderRadius: "8px",
                padding: "18px",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              <span
                style={{
                  fontFamily: cormorantFamily,
                  fontSize: `${bodyFontSize * 1.3}px`,
                  color: "#58c4dd",
                  fontStyle: "italic",
                  letterSpacing: "1px",
                }}
              >
                ds² = -c²dt² + dx² + dy² + dz²
              </span>
            </div>
          </div>
        )}

        {/* Stage 2: Mass Intro */}
        {text2Opacity > 0 && (
          <div
            style={{
              transform: `translateY(${text2Y}px)`,
              opacity: text2Opacity,
              position: "absolute",
              inset: "40px 32px",
              display: "flex",
              flexDirection: "column",
              justifyContent: "flex-start",
              transition: "none",
            }}
          >
            <div
              style={{
                color: "#ff7675",
                fontFamily: interFamily,
                fontSize: `${metaFontSize}px`,
                fontWeight: "bold",
                letterSpacing: "3px",
                marginBottom: "12px",
              }}
            >
              STAGE 2: COUPLING CONSTANT
            </div>
            <div
              style={{
                fontFamily: cormorantFamily,
                fontSize: `${titleFontSize}px`,
                color: "#ffffff",
                lineHeight: "1.2",
                marginBottom: "20px",
              }}
            >
              Mass Curvature
            </div>
            <div
              style={{
                fontFamily: interFamily,
                fontSize: `${bodyFontSize}px`,
                color: "#b2bec3",
                lineHeight: "1.7",
                marginBottom: "32px",
              }}
            >
              A massive black hole contracts the local spacetime coordinate structure. Coordinate lines compress and bend severely inwards toward the center of mass.
            </div>
            <div
              style={{
                backgroundColor: "rgba(255, 118, 117, 0.04)",
                border: "1px solid rgba(255, 118, 117, 0.15)",
                borderRadius: "8px",
                padding: "18px",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  fontFamily: cormorantFamily,
                  fontSize: `${bodyFontSize * 1.4}px`,
                  color: "#ff7675",
                  fontStyle: "italic",
                }}
              >
                <span>G</span>
                <sub style={{ fontSize: `${metaFontSize * 0.85}px`, transform: "translateY(3px)" }}>μν</sub>
                <span style={{ margin: "0 10px" }}>=</span>
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    margin: "0 6px",
                  }}
                >
                  <span style={{ borderBottom: "1.5px solid #ff7675", paddingBottom: "2px", lineHeight: "1" }}>8πG</span>
                  <span style={{ fontSize: `${bodyFontSize * 1.05}px`, lineHeight: "1.1" }}>c⁴</span>
                </div>
                <span>T</span>
                <sub style={{ fontSize: `${metaFontSize * 0.85}px`, transform: "translateY(3px)" }}>μν</sub>
              </div>
            </div>
          </div>
        )}

        {/* Stage 3: Gravitational Lensing / Deflection */}
        {text3Opacity > 0 && (
          <div
            style={{
              transform: `translateY(${text3Y}px)`,
              opacity: text3Opacity,
              position: "absolute",
              inset: "40px 32px",
              display: "flex",
              flexDirection: "column",
              justifyContent: "flex-start",
              transition: "none",
            }}
          >
            <div
              style={{
                color: "#fdcb6e",
                fontFamily: interFamily,
                fontSize: `${metaFontSize}px`,
                fontWeight: "bold",
                letterSpacing: "3px",
                marginBottom: "12px",
              }}
            >
              STAGE 3: NULL GEODESICS
            </div>
            <div
              style={{
                fontFamily: cormorantFamily,
                fontSize: `${titleFontSize}px`,
                color: "#ffffff",
                lineHeight: "1.2",
                marginBottom: "20px",
              }}
            >
              Light Deflection
            </div>
            <div
              style={{
                fontFamily: interFamily,
                fontSize: `${bodyFontSize}px`,
                color: "#b2bec3",
                lineHeight: "1.7",
                marginBottom: "24px",
              }}
            >
              Massless photons follow coordinate pathways. Because the spacetime grid is curved, paths deflect dynamically around the black hole.
            </div>

            {/* Educational Legend */}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: "14px",
                borderTop: "1px solid rgba(255, 255, 255, 0.08)",
                paddingTop: "20px",
              }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                <div style={{ width: "24px", height: "4px", backgroundColor: "#2ECC71", borderRadius: "2px" }} />
                <span style={{ fontFamily: interFamily, fontSize: `${metaFontSize}px`, color: "#dfe6e9", fontWeight: "500" }}>
                  Weak Lensing (distant approach)
                </span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                <div style={{ width: "24px", height: "4px", backgroundColor: "#F1C40F", borderRadius: "2px" }} />
                <span style={{ fontFamily: interFamily, fontSize: `${metaFontSize}px`, color: "#dfe6e9", fontWeight: "500" }}>
                  Severe Relativistic Deflection
                </span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
                <div style={{ width: "24px", height: "4px", backgroundColor: "#E74C3C", borderRadius: "2px" }} />
                <span style={{ fontFamily: interFamily, fontSize: `${metaFontSize}px`, color: "#dfe6e9", fontWeight: "500" }}>
                  Captured (Crossed Event Horizon)
                </span>
              </div>
            </div>
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default SpacetimeBending;